import { spawnSync } from "node:child_process";
import { mkdtempSync, readFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const packageEsm = source => source
  .replace(
    "// @generated by protoc-gen-es v2.14.1\n",
    "// @generated by protoc-gen-es v2.14.1; packaged with explicit ESM import extensions\n",
  )
  .replace(/from "(\.\.?\/[^\"]+)";/g, (statement, specifier) =>
    specifier.endsWith(".js") ? statement : `from "${specifier}.js";`);
const temporary = mkdtempSync(join(tmpdir(), "acyclic-sdk-codegen-"));
try {
  const descriptor = join(temporary, "filesystem.bin");
  const executable = join(root, "node_modules", ".bin", process.platform === "win32" ? "buf.exe" : "buf");
  const built = spawnSync(executable, ["build", "--path", "proto/filesystem", "-o", descriptor], {
    cwd: root,
    encoding: "utf8",
  });
  if (built.status !== 0) {
    process.stderr.write(built.stdout ?? "");
    process.stderr.write(built.stderr ?? "");
    throw new Error(`buf build failed with status ${built.status ?? "unknown"}`);
  }
  const committed = join(root, "rust/crates/filesystem/src/generated/acyclic-filesystem-v2.bin");
  if (!readFileSync(descriptor).equals(readFileSync(committed))) {
    throw new Error("filesystem descriptor is stale; run bun run generate");
  }

  for (const relative of [
    "filesystem/v2/filesystem_pb.js",
    "filesystem/v2/filesystem_pb.d.ts",
    "filesystem/daemon/v2/daemon_pb.js",
    "filesystem/daemon/v2/daemon_pb.d.ts",
    "harness/v1/harness_pb.js",
    "harness/v1/harness_pb.d.ts",
  ]) {
    const canonical = packageEsm(
      readFileSync(join(root, "generated/typescript", relative), "utf8"),
    );
    const packaged = readFileSync(
      join(root, "typescript/packages/filesystem/generated/proto", relative),
      "utf8",
    );
    if (canonical !== packaged) throw new Error(`packaged TypeScript drift: ${relative}`);
  }
} finally {
  rmSync(temporary, { recursive: true, force: true });
}
